   "confidence": 0.8
  }
 ],
 "actions": [
  {
   "action": "inspect",
   "args": {
    "what": "canaries",
    "component": "replica-1",
    "contains": "Arabic fact"
   },
   "hypothesis": "H2",
   "purpose": "investigate",
   "why": "Verify if replica-1's Arabic fact failure is due to vector search (retrieval) or internal knowledge, to distinguish between index corruption and model version issues."
  },
  {
   "action": "inspect",
   "args": {
    "what": "canaries",
    "component": "replica-4",
    "contains": "English fact"
   },
   "hypothesis": "H2",
   "purpose": "investigate",
   "why": "Check if replica-4's English fact failure is isolated or part of a broader pattern, given its different template."
  },
  {
   "action": "rollback",
   "args": {
    "key": "model_version",
    "replicas": [
     "replica-1",
     "replica-2",
     "replica-3",
     "replica-4"
    ]
   },
   "hypothesis": "H2",
   "purpose": "fix",
   "why": "Since H2 (index corruption) has been ruled out as the sole cause by the persistence after failover/rebuild, and all replicas share the new model version v2.4-rc which was deployed simultaneously with the symptoms, it is highly likely the new model version contains hallucinations or regression in factual/retrieval tasks. Rolling back will test this hypothesis."
  }
